//! macOS side of the clipboard history: NSPasteboard's change counter, items to skip,
//! and the app that was in front.

use std::sync::atomic::{AtomicI32, Ordering};

use objc2::{class, msg_send, rc::autoreleasepool, runtime::AnyObject};
use objc2_foundation::{NSArray, NSString};

/// Pasteboard types that password managers and similar apps add to say "don't keep
/// this" (see nspasteboard.org).
const SKIP_TYPES: [&str; 5] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType",
];

/// Process id of the app that was in front when the popup opened.
static PREVIOUS_PID: AtomicI32 = AtomicI32::new(0);

fn with_pasteboard<T>(default: T, f: impl FnOnce(&AnyObject) -> T) -> T {
    autoreleasepool(|_| unsafe {
        let board: *mut AnyObject = msg_send![class!(NSPasteboard), generalPasteboard];
        match board.as_ref() {
            Some(board) => f(board),
            None => default,
        }
    })
}

pub fn change_count() -> i64 {
    with_pasteboard(-1, |board| {
        let count: isize = unsafe { msg_send![board, changeCount] };
        count as i64
    })
}

pub fn should_skip() -> bool {
    with_pasteboard(false, |board| unsafe {
        let types: *mut NSArray<NSString> = msg_send![board, types];
        types.as_ref().is_some_and(|types| {
            types
                .iter()
                .any(|t| SKIP_TYPES.contains(&t.to_string().as_str()))
        })
    })
}

pub fn remember_foreground() {
    autoreleasepool(|_| unsafe {
        let workspace: *mut AnyObject = msg_send![class!(NSWorkspace), sharedWorkspace];
        let Some(workspace) = workspace.as_ref() else {
            return;
        };
        let front: *mut AnyObject = msg_send![workspace, frontmostApplication];
        let Some(front) = front.as_ref() else { return };
        let pid: i32 = msg_send![front, processIdentifier];
        if pid > 0 && pid as u32 != std::process::id() {
            PREVIOUS_PID.store(pid, Ordering::SeqCst);
        }
    });
}

/// Brings back the app that was in front when the popup opened.
pub fn activate_previous() {
    let pid = PREVIOUS_PID.load(Ordering::SeqCst);
    if pid <= 0 {
        return;
    }
    autoreleasepool(|_| unsafe {
        let app: *mut AnyObject = msg_send![
            class!(NSRunningApplication),
            runningApplicationWithProcessIdentifier: pid
        ];
        if let Some(app) = app.as_ref() {
            // NSApplicationActivateIgnoringOtherApps
            let _: bool = msg_send![app, activateWithOptions: 2usize];
        }
    });
}
